  assert.equal(LOG_OPEN_COMBINE_INBOUND_CALLSITES, 46);
  assert.equal(LOG_OPEN_COMBINE_RAW_OCCURRENCES, 0);
  assert.equal(LOG_OPEN_COMBINE_SEP_SLASH, 0x2f);
  assert.equal(LOG_OPEN_COMBINE_SEP_BACKSLASH, 0x5c);
