  assert.equal(LOG_OPEN_COMBINE_ALLOC_VA, 0x00a648b0);
  assert.equal(LOG_OPEN_COMBINE_VSPRINTF_S_VA, 0x00652a30);
  assert.equal(LOG_OPEN_COMBINE_OPTIONS_GETTER, 0x0041d4c0);
